import { BitmapText } from '@a3d/a3d-components/core';

// 基础中文文本
const text = new BitmapText({
  text: 'Hello 世界',
  fontSize: 72,
  width: 1000,
  align: 'center',
});
scene.add(text);

// 带描边和阴影
const fancy = new BitmapText({
  text: '道可道，非常道',
  fontSize: 64,
  outline: true,
  outlineColor: 0x00bbff,
  outlineWidth: 0.06,
  shadow: true,
  scale: 0.01,
});
scene.add(fancy);

// 运行时更新
text.setText('新的文字内容');
text.setColor(0xffcc00);
fancy.setOutline(true);
fancy.setOutlineParams(0xff0000, 0.08, 1);

// 清理
text.dispose();

import { Grid } from '@a3d/a3d-components/core';

// 作为无限地面参考网，自定义网格与坐标轴颜色
const grid = new Grid({
  primaryScale: 5,
  secondaryScale: 1,
  color: '#9aa7b8',       // 网格线颜色
  xAxisColor: 0xff5555,   // X 轴
  zAxisColor: 0x55aaff,   // Z / Y 轴
});
scene.add(grid);

// 运行时调整样式（所有 setter 链式调用）
grid.setShowAxis(false).setLinearFade(true).setFade(20, 80);
grid.setColor('#ffffff').setXAxisColor('red');

// 平滑切换到 2D 立面网格（GSAP 动画）
grid.setPlane('xy');

import { Html } from '@a3d/a3d-components/core';

// ── 基础标签 ──
const label = new Html({ center: true });
label.position.set(0, 2, 0);
label.element.innerHTML = '<div style="background:#fff;padding:8px 16px;border-radius:4px;box-shadow:0 2px 8px rgba(0,0,0,.15)">Hello 3D!</div>';
scene.add(label);

// ── 带距离缩放 ──
const info = new Html({
  distanceFactor: 10,
  center: true,
  style: 'background:rgba(0,0,0,.75);color:#fff;padding:10px;border-radius:6px;',
});
info.position.set(1, 1.5, -1);
info.element.innerHTML = '距离缩放标签';
scene.add(info);

// ── CSS3D 变换模式 ──
const panel = new Html({
  transform: true,
  distanceFactor: 10,
});
panel.position.set(0, 1.2, -3);
panel.element.innerHTML = '<div style="width:300px;background:white;padding:20px">3D 面板</div>';
scene.add(panel);

// ── 射线遮挡 ──
const occluded = new Html({
  center: true,
  occlude: 'raycast',
  onOcclude: (hidden) => console.log('遮挡状态:', hidden),
});
occluded.position.set(0, 0.5, 0);
scene.add(occluded);

// ── 渲染循环 ──
function animate() {
  requestAnimationFrame(animate);
  const delta = clock.getDelta();
  label.update(delta, camera, renderer);
  info.update(delta, camera, renderer);
  panel.update(delta, camera, renderer);
  occluded.update(delta, camera, renderer);
  renderer.render(scene, camera);
}

// ── 清理 ──
label.dispose();
info.dispose();

import { InstancedMesh2 } from '@a3d/a3d-components/core';
import * as THREE from 'three';

// 基础用法：创建 5000 个实例
const mesh = new InstancedMesh2(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({ color: 0x44aa88 }),
  { capacity: 5000, createEntities: true, allowsEuler: true },
);

mesh.addInstances(5000, (obj, i) => {
  obj.position.set(Math.random() * 100 - 50, 0, Math.random() * 100 - 50);
  obj.rotation.y = Math.random() * Math.PI * 2;
  obj.updateMatrix();
});
scene.add(mesh);

// 启用 BVH 加速视锥裁剪
mesh.computeBVH({ getBBoxFromBSphere: true });

// LOD：4 级细节，距离越远越简化
mesh.setFirstLODDistance(0);
mesh.addLOD(geoL1, matL1, 15);   // 15 单位内用 L1
mesh.addLOD(geoL2, matL2, 40);   // 40 单位内用 L2
mesh.addLOD(geoL3, matL3, 80);   // 80 单位内用 L3

// 逐实例颜色
mesh.setColorAt(0, new THREE.Color('red'));

// 逐实例自定义 Uniform
mesh.initUniformsPerInstance({
  vertex: { windStrength: 'float', windDir: 'vec2' },
});
mesh.setUniformAt(0, 'windStrength', 0.8);
mesh.setUniformAt(0, 'windDir', new THREE.Vector2(1, 0));

import { Outlines } from '@a3d/a3d-components/core';

// 给一个普通网格加描边
const mesh = new THREE.Mesh(geometry, material);
const outline = new Outlines({ mesh, color: 'red', thickness: 0.05 });
mesh.add(outline); // 描边作为 mesh 的子级，自动跟随变换 / 骨架
scene.add(mesh);

// 屏幕空间恒定线宽（卡通描边风格）
const toon = new Outlines({
  mesh, color: 'black', thickness: 0.01, screenspace: true,
});
toon.attachRenderer(renderer); // 让组件读取画布尺寸做归一化
mesh.add(toon);

// 切换折痕角度（运行时重建）
outline.setAngle(Math.PI / 4);

import { Path } from '@a3d/a3d-components/core';

// 3D 折线 → 圆管（拐角倒圆角 + 起终点封盖）
const tube = new Path({
  paths: [{
    path: [[0,0,0],[3,0,0],[3,3,0],[0,3,0]],
    mode: 'tube', bevelRadius: 0.5, radius: 0.15,
    generateStartCap: true, generateEndCap: true,
  }],
});
scene.add(tube);

// 2D 折线 → 扁平带（锐角修补 + 末端箭头）
const route = new Path({
  paths: [{
    path: [[0,0,0],[3,0,0],[3,0,3],[0,0,3]],
    mode: 'plane', bevelRadius: 0, width: 0.5,
    side: 'both', sharp: true, arrow: true, up: [0,1,0],
  }],
});
scene.add(route);

// 闭合环形管道（首尾自动相连，标架同步）
const ring = new Path({
  paths: [{
    path: [[2,0,0],[0,0,2],[-2,0,0],[0,0,-2]],
    mode: 'tube', close: true, radius: 0.1, radialSegments: 12,
  }],
});
scene.add(ring);

// 带流光的管道（青色光带 + 拖尾，从起点流向终点）
const flow = new Path({
  paths: [{
    path: [[0,0,0],[3,0,0],[3,0,3],[0,0,3]],
    mode: 'tube', bevelRadius: 0.4, radius: 0.12,
  }],
  flow: { enabled: true, color: 0x00ffff, speed: 0.5, tailLength: 0.5, intensity: 2.5 },
});
scene.add(flow);
// 运行时调整：flow.setFlowDirection(-1).setFlowRepeat(3);

import { Rack } from '@a3d/a3d-components/core';

// 4 货位 × 3 层、深 1m 的等分货架，每货位一块 60% 宽层板
const rack = new Rack({
  data: { row: 4, col: 3, width: 1.2, height: 0.8, depth: 1, goodsPlank: '60' },
});
scene.add(rack);

// 数据驱动重建：只改层数，其余沿用
rack.set({ col: 5 });

// 逐货位宽度 + 逐层高度 + 最底层层板
rack.set({
  row: [1, 2, 1],
  col: [0.5, 1, 1.5],
  firstplane: true,
});

// 显式层板：完全自定义每块层板的位置与尺寸
rack.set({
  goodsPlank: [{ position: { x: 1, y: 1, z: -0.5 }, width: 0.6, depth: 0.9 }],
});

import { Shape } from '@a3d/a3d-components/core';

// L 形异形台面，统一圆角
const shape = new Shape({
  shapes: [{
    path: [[0,0,0], [4,0,0], [4,0,2], [2,0,2], [2,0,5], [0,0,5]],
    height: 0.6,
    radius: 0.3,
    radiusSegments: 12,
    uvMode: 'repeat',
  }],
});
scene.add(shape);

// 混合圆角：第 0、3 个拐角 0.5，其余用全局值 0
const shape2 = new Shape({
  shapes: [{
    path: [[0,0,0], [3,0,0], [3,0,3], [0,0,3]],
    height: 0.4,
    radius: [0.5, undefined, undefined, 0.5],
    radiusSegments: 12,
  }],
});
scene.add(shape2);

import { Sky } from '@a3d/a3d-components/core';

// 天空穹顶
const sky = new Sky({
  size: 500,
  topColor: 0x109df4,
  bottomColor: 0xf5f5f5,
  offset: 0,
  exponent: 0.6,
});
scene.add(sky);

// 运行时调整颜色（所有 setter 链式调用）
sky.setTopColor(0x1a8af4).setBottomColor(0xe0e0e0);
sky.setOffset(10).setExponent(0.8);

// 同时设置天顶与地平线颜色
sky.setColors(0x109df4, 0xf5f5f5);

import { Wall } from '@a3d/a3d-components/core';

const wall = new Wall({
  walls: [
    {
      // 闭合矩形房间，带圆角
      path: [[0, 0, 0], [6, 0, 0], [6, 0, 5], [0, 0, 5]],
      width: 0.25,
      height: 3,
      radius: 1,
      radiusSegments: 16,
      close: true,
      hole: [
        // 第 0 段（[0,0,0]→[6,0,0]）上的一扇门：沿墙 2~4m、高 0~2.1m
        { segment: 0, path: [[2, 0], [4, 0], [4, 2.1], [2, 2.1]] },
        // 第 1 段（[6,0,0]→[6,0,5]）上的一扇窗：沿墙 1.5~3.5m、离地 1~1.8m
        { segment: 1, path: [[1.5, 1], [3.5, 1], [3.5, 1.8], [1.5, 1.8]], radius: 0.15 },
      ],
    },
    {
      // 开放隔墙，圆角拐角（首尾不闭合）
      path: [[-2, 0, 8], [2, 0, 8], [2, 0, 11]],
      width: 0.2,
      height: 2.5,
      radius: 0.8,
    },
  ],
});
scene.add(wall);

import { Wireframe } from '@a3d/a3d-components/core';

// 独立线框（父级材质不受影响）
const mesh = new THREE.Mesh(geometry, standardMaterial);
const wf = new Wireframe({
  mesh, stroke: '#ff0000', thickness: 0.1, dash: true,
});
mesh.add(wf); // 作为子级，自动跟随父级变换
scene.add(mesh);

// 带光照的线框模型（注入 PBR 材质）
const lit = new Wireframe({
  mesh, overrideMaterial: true,
  fillMix: 0.5,    // 一半原色 / 一半 fill
  stroke: '#111111', fill: '#88ccff',
});
mesh.add(lit);

// 运行时调参（链式）
wf.setUniform('thickness', 0.2).setUniform('stroke', 'blue');
